import {registerCatalog} from './i18n.js';
registerCatalog('annualMetrics',{en:{
 taxTerminal:'Annual tax & terminal',title:'Annual operating uncertainty',enable:'Use separate annual paths for operating inputs',method:'Operating-input sampling method',annual:'Correlated annual operating paths',legacy:'Legacy scalar input draws',margin:'EBIT margin',taxRate:'Operating tax rate',wacc:'Annual WACC',salesCapital:'Incremental sales / capital',reinvestment:'Signed net investment',investmentFactor:'Net-investment response factor',sd:'Innovation SD · {unit}',persistence:'Year-to-year persistence',pp:'percentage points',ratio:'ratio units',factor:'multiple units',money:'{currency} millions',year:'Year {year} · {value}',fixed:'Fixed',variable:'Variable',fixedNote:'Select a year to hold this primitive input exactly at its edited baseline. Zero SD removes annual innovation noise; a changed terminal endpoint can still shift the conditional mean. Derived outcomes still respond to other inputs.',note:'Each primitive has its own Gaussian AR(1) deviations, conditioned on selected baseline years and the terminal endpoint. User-fixed years remain exact. With zero SD, annual paths can still move deterministically toward sampled terminal endpoints. Nonzero SDs are analyst assumptions, not sourced or calibrated volatility. Innovations are independent across metrics; invalid paths are excluded without clipping or replacement.',scopeGuided:'Annual growth determines revenue. Annual margin, tax and WACC determine earnings and discounting. Annual sales / capital determines investment. Scalar margin and WACC distributions control terminal endpoints only; the scalar sales / capital distribution is inactive. Revenue, NOPAT, FCFF and implied returns are derived, never sampled twice.',scopeResearch:'Annual growth determines revenue; margin, tax and WACC have separate paths. With fixed-schedule and factor 1, edited pre-reserve investment stays fixed; revenue-responsive policies may change it. Selected fixed funding stays outside factors; required operating-cash changes are derived separately. Scalar margin/WACC shifts control terminal endpoints only; the scalar investment multiplier is inactive. Earnings, FCFF, discount factors and implied returns are derived, not sampled again.',terminal:'Terminal scalar uncertainty',growth:'Stable growth',roic:'Terminal marginal ROIC',terminalTax:'Terminal tax rate',terminalNote:'These rates are drawn once per scenario. Growth, tax and marginal ROIC default to the current fixed terminal assumptions. Existing scalar margin and WACC controls set terminal targets. WACC and ROIC must exceed stable growth. Terminal growth is capped at 5%; invalid combinations are excluded. Sampled stable growth becomes the maturity endpoint and stays constant across its plateau. User-fixed growth years at or after maturity require terminal growth fixed at baseline.',type:'Distribution',fixedType:'Fixed',uniform:'Uniform',triangular:'Triangular',normal:'Bounded normal',value:'Value · %',low:'Low · %',high:'High · %',mode:'Mode · %',mean:'Underlying mean · %',normalSD:'Underlying SD · pp',preview:'{metric} · completed scenario paths',fixedFacts:'Source financials, historical anchors, forecast horizon, timing and dated claims inputs remain fixed. Claims that the existing model reprices still use each trial value. Losses receive no automatic tax credits or NOL carryforward.',defaults:'New annual operating SDs start at zero until edited. The existing growth uncertainty and terminal scalar assumptions remain visible and editable.',relationship:'Annual primitive innovations are independent across metrics, with separate serial persistence. Any selected operating-linked setting affects only remaining scalar terminal draws; it does not correlate annual innovations.'
},'zh-Hans':{
 taxTerminal:'年度税率与终值',title:'年度经营不确定性',enable:'为经营输入使用独立年度路径',method:'经营输入抽样方式',annual:'相关年度经营路径',legacy:'原有标量输入抽样',margin:'EBIT 利润率',taxRate:'经营税率',wacc:'年度 WACC',salesCapital:'增量销售额 / 资本',reinvestment:'有符号净再投资',investmentFactor:'净投资响应系数',sd:'创新标准差 · {unit}',persistence:'年度持续性',pp:'百分点',ratio:'比率单位',factor:'倍数单位',money:'百万{currency}',year:'第 {year} 年 · {value}',fixed:'固定',variable:'可变',fixedNote:'选择年份可将该原始输入精确固定在已编辑基准值。标准差为零时不产生年度创新噪声，但终值端点变化仍可改变条件均值；衍生结果仍会随其他输入变化。',note:'每个原始输入使用独立的高斯 AR(1) 偏差，并以所选基准年份和终值端点为条件。用户固定年份始终保持精确值。标准差为零时，年度路径仍可确定性地向抽样终值端点移动。非零标准差属于分析者假设，并非有来源或经校准的波动率。不同指标的创新相互独立；无效路径直接排除，不截断或补抽。',scopeGuided:'年度增长决定收入。年度利润率、税率和 WACC 决定盈利及折现。年度销售额 / 资本决定再投资。标量利润率和 WACC 分布仅控制终值端点；标量销售额 / 资本分布不启用。收入、NOPAT、FCFF 和隐含回报均由模型推导，不重复抽样。',scopeResearch:'年度增长决定收入；利润率、税率和 WACC 使用各自路径。采用固定计划且系数为 1 时，编辑后的储备前投资保持不变；响应收入的政策则可能改变该金额。所选固定资金支出不乘以系数；所需经营现金变化另行推导。标量利润率和 WACC 偏移仅控制终值端点；标量投资倍数不启用。盈利、FCFF、折现因子和隐含回报由模型推导，不重复抽样。',terminal:'终值标量不确定性',growth:'稳定增长率',roic:'终值边际 ROIC',terminalTax:'终值税率',terminalNote:'每个情景对这些比率抽样一次。增长率、税率和边际 ROIC 默认采用当前固定终值假设。原有标量利润率和 WACC 控件设置终值目标。WACC 和 ROIC 必须高于稳定增长率。终值增长率上限为 5%；无效组合将被排除。抽样稳定增长率成为成熟端点，并在其平台期保持不变。成熟年及之后若有用户固定增长年份，终值增长率必须固定为基准值。',type:'分布',fixedType:'固定',uniform:'均匀',triangular:'三角',normal:'有界正态',value:'数值 · %',low:'下限 · %',high:'上限 · %',mode:'众数 · %',mean:'底层均值 · %',normalSD:'底层标准差 · 百分点',preview:'{metric} · 已完成情景路径',fixedFacts:'来源财务数据、历史锚点、预测期限、时点和注明日期的索偿权输入保持固定。现有模型会重新定价的索偿权仍使用每次情景估值。亏损不会自动产生税收抵免或亏损结转。',defaults:'新增年度经营标准差在编辑前均为零。现有增长不确定性及终值标量假设仍可查看和编辑。',relationship:'不同年度原始输入的创新相互独立，并具有各自的年度持续性。所选经营关联设置仅影响其余终值标量抽样，不会使年度创新相关。'
}});
// Whole-message keys keep units and metric names responsive to locale changes.
registerCatalog('annualMetrics',{en:{sdPP:'Innovation SD · percentage points',sdRatio:'Innovation SD · ratio units',sdFactor:'Innovation SD · multiple units',sdMoney:'Innovation SD · {currency} millions',growthFixedNote:'Selected pre-maturity years keep their exact edited baseline growth. Growth at and after maturity follows the terminal growth setting. Displayed rates are rounded; fixed years use exact model values.'},'zh-Hans':{sdPP:'创新标准差 · 百分点',sdRatio:'创新标准差 · 比率单位',sdFactor:'创新标准差 · 倍数单位',sdMoney:'创新标准差 · 百万{currency}',growthFixedNote:'所选成熟前年份保持编辑后的精确基准增长率。成熟年及之后的增长遵循终值增长设置。显示的比率经过四舍五入；固定年份使用精确模型数值。'}});
for(const [key,en,zh]of [['margin','EBIT margin','EBIT 利润率'],['taxRate','Operating tax rate','经营税率'],['wacc','Annual WACC','年度 WACC'],['salesCapital','Incremental sales / capital','增量销售额 / 资本'],['reinvestment','Signed net investment','有符号净投资'],['investmentFactor','Net-investment response factor','净投资响应系数']])registerCatalog('annualMetrics',{en:{['preview.'+key]:en+' · completed scenario paths'},'zh-Hans':{['preview.'+key]:zh+' · 已完成情景路径'}});
registerCatalog('annualMetrics',{en:{terminalLinked:'Terminal setting',terminalYearAria:'Year {year}: baseline growth {growth}%; follows the terminal growth setting',terminalBaseline:'Baseline terminal growth: {growth}%. Scenario endpoints follow the terminal growth uncertainty setting.'},'zh-Hans':{terminalLinked:'终值设置',terminalYearAria:'第 {year} 年：基准增长率 {growth}%；遵循终值增长设置',terminalBaseline:'基准终值增长率：{growth}%。情景端点遵循终值增长不确定性设置。'}});
